// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time, enabling deterministic testing.
type Clock interface {
	Now() time.Time
}

// RealClock uses the system clock.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu         sync.Mutex
	capacity   int
	tokens     int
	refillRate float64 // tokens per second
	last       time.Time
	clock      Clock
}

// NewTokenBucket creates a TokenBucket with the given capacity (max burst)
// and refillRate (tokens per second). Returns an error on invalid parameters.
func NewTokenBucket(capacity int, refillRate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if refillRate <= 0 {
		return nil, errors.New("ratelimit: refillRate must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &TokenBucket{
		capacity:   capacity,
		tokens:     capacity,
		refillRate: refillRate,
		last:       clock.Now(),
		clock:      clock,
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if the tokens were
// available and consumed, false otherwise.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	tb.tokens += int(elapsed * tb.refillRate)
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= n {
		tb.tokens -= n
		return true
	}
	return false
}

// Allow is a convenience wrapper for AllowN(1).
func (tb *TokenBucket) Allow() bool { return tb.AllowN(1) }
