package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time, enabling deterministic testing.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu         sync.Mutex
	capacity   float64
	tokens     float64
	refillRate float64 // tokens per second
	last       time.Time
	clock      Clock
}

// New creates a Limiter with the given capacity and refill rate (tokens/sec).
// The clock is used for time measurement; pass a real or fake clock.
func New(capacity, refillRate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if refillRate <= 0 {
		return nil, errors.New("ratelimit: refillRate must be positive")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity,
		refillRate: refillRate,
		last:       clock.Now(),
		clock:      clock,
	}, nil
}

// AllowN reports whether n tokens are available and consumes them if so.
// It returns false without consuming if n exceeds remaining tokens.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.refillRate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is shorthand for AllowN(1).
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// Tokens returns the current token count (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.refillRate
	if t > l.capacity {
		t = l.capacity
	}
	return t
}
